source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    solid_rows = [(r, row[0]) for r, row in enumerate(grid)
                  if row[0] != 0 and all(value == row[0] for value in row)]
    if solid_rows:
        for period in range(1, h + 1):
            phases = {}
            valid = True
            for r, color in solid_rows:
                phase = r % period
                if phase in phases and phases[phase] != color:
                    valid = False
                    break
                phases[phase] = color
            if valid:
                pattern = [phases[i] for i in range(period)]
                return [[pattern[r % period] for _ in range(w)] for r in range(h)]

    # Otherwise, the colored cells mark diagonal phases of a repeating tile.
    for period in range(1, max(h, w) + 1):
        phases = {}
        valid = True
        for r, row in enumerate(grid):
            for c, color in enumerate(row):
                if color == 0:
                    continue
                phase = (c - r) % period
                if phase in phases and phases[phase] != color:
                    valid = False
                    break
                phases[phase] = color
            if not valid:
                break
        if valid:
            pattern = [phases[i] for i in range(period)]
            return [[pattern[(c - r) % period] for c in range(w)] for r in range(h)]
    raise ValueError("No consistent periodic pattern found")
'''
